//! The consumer key and secret that identify the application to USOS. Values are never
//! printed or logged.
//!
//! Resolution order (see [`resolve`]): a key the caller supplies explicitly
//! (`ConsumerSource::Fixed`, handled by the session), then runtime environment variables, then
//! the key embedded at compile time for that installation (see `build.rs`).

use crate::client::normalize_base_url;
use crate::error::{Error, Result};
use crate::secret::Secret;

// Generated by `build.rs`: `EMBEDDED: Option<(key, secret, base_url)>`.
mod generated {
    include!(concat!(env!("OUT_DIR"), "/embedded_key.rs"));
}

const KEY_NAMES: [&str; 2] = ["USOS_CONSUMER_KEY", "CONSUMER_KEY"];
const SECRET_NAMES: [&str; 2] = ["USOS_CONSUMER_SECRET", "CONSUMER_SECRET"];

/// The consumer key and secret that identify the application to USOS.
/// `Debug` shows `Secret(***)` for both fields; there is no `Display`.
#[derive(Debug, Clone)]
pub struct Consumer {
    pub key: Secret,
    pub secret: Secret,
}

impl Consumer {
    /// Runtime environment variables only (`USOS_CONSUMER_KEY`/`USOS_CONSUMER_SECRET`, then the
    /// legacy `CONSUMER_KEY`/`CONSUMER_SECRET`). `None` unless both are set and non-empty.
    pub fn from_env() -> Option<Self> {
        from_lookup(|name| std::env::var(name).ok())
    }
}

fn from_lookup(get: impl Fn(&str) -> Option<String>) -> Option<Consumer> {
    let first = |names: &[&str]| names.iter().filter_map(|n| get(n)).find(|v| !v.is_empty());
    Some(Consumer {
        key: Secret::new(first(&KEY_NAMES)?),
        secret: Secret::new(first(&SECRET_NAMES)?),
    })
}

/// The consumer embedded at compile time for the installation at `base_url`, if any.
///
/// The key is injected by `build.rs` (`USOS_CONSUMER_KEY`, `USOS_CONSUMER_SECRET`,
/// `USOS_KEY_BASE_URL`, or the workspace `.env`). It is `None` when the build had no key, or
/// when it belongs to another installation. URLs are compared normalized (scheme, host case,
/// trailing slash), so support for more universities can be added later by embedding more keys.
pub fn embedded(base_url: &str) -> Option<Consumer> {
    embedded_from(generated::EMBEDDED, base_url)
}

fn embedded_from(spec: Option<(&str, &str, &str)>, base_url: &str) -> Option<Consumer> {
    let (key, secret, key_base_url) = spec?;
    let wanted = normalize_base_url(base_url).ok()?;
    let have = normalize_base_url(key_base_url).ok()?;
    (wanted == have).then(|| Consumer {
        key: Secret::new(key),
        secret: Secret::new(secret),
    })
}

/// Default resolution for the installation at `base_url`: runtime environment variables, then
/// the embedded key. (An explicitly supplied consumer is handled before this, by the session.)
pub fn resolve(base_url: &str) -> Result<Consumer> {
    Consumer::from_env()
        .or_else(|| embedded(base_url))
        .ok_or(Error::ConsumerNotConfigured)
}

#[cfg(test)]
mod tests {
    use super::*;

    const FAKE_SECRET: &str = "s3cr3t-fake-value";
    const FAKE_KEY: &str = "k3y-fake-value";

    #[test]
    fn debug_never_shows_the_values() {
        let c = Consumer {
            key: Secret::new(FAKE_KEY),
            secret: Secret::new(FAKE_SECRET),
        };
        for text in [
            format!("{c:?}"),
            format!("{c:#?}"),
            format!("{:?}", Some(&c)),
        ] {
            assert!(!text.contains(FAKE_SECRET), "{text}");
            assert!(!text.contains(FAKE_KEY), "{text}");
            assert!(text.contains("Secret(***)"));
        }
        assert_eq!(format!("{:?}", c.secret), "Secret(***)");
    }

    #[test]
    fn embedded_matches_normalized_base_urls() {
        let spec = Some((FAKE_KEY, FAKE_SECRET, "https://usosapi.polsl.pl/"));
        for url in [
            "https://usosapi.polsl.pl/",
            "https://usosapi.polsl.pl",
            "HTTPS://USOSAPI.POLSL.PL/",
            "usosapi.polsl.pl",
            " https://usosapi.polsl.pl/?x=1#y ",
        ] {
            let c = embedded_from(spec, url).unwrap_or_else(|| panic!("no match for {url}"));
            assert_eq!(c.key.expose(), FAKE_KEY);
            assert_eq!(c.secret.expose(), FAKE_SECRET);
        }
        for url in [
            "https://usos.example/",
            "https://usosapi.polsl.pl/v2/",
            "",
            "ftp://x",
        ] {
            assert!(embedded_from(spec, url).is_none(), "{url}");
        }
        assert!(embedded_from(None, "https://usosapi.polsl.pl/").is_none());
    }

    #[test]
    fn env_lookup_prefers_prefixed_names_and_ignores_empty() {
        let env = |pairs: &'static [(&'static str, &'static str)]| {
            move |n: &str| {
                pairs
                    .iter()
                    .find(|(k, _)| *k == n)
                    .map(|(_, v)| (*v).to_owned())
            }
        };
        let c = from_lookup(env(&[
            ("USOS_CONSUMER_KEY", ""),
            ("CONSUMER_KEY", "legacy-k"),
            ("USOS_CONSUMER_SECRET", "new-s"),
            ("CONSUMER_SECRET", "legacy-s"),
        ]))
        .unwrap();
        assert_eq!(c.key.expose(), "legacy-k");
        assert_eq!(c.secret.expose(), "new-s");
        assert!(from_lookup(env(&[("USOS_CONSUMER_KEY", "k")])).is_none());
    }
}
